add_action( 'woocommerce_shutdown_error', 'perfectpixel_email_on_fatal_error' );

function perfectpixel_email_on_fatal_error( $error ) {
	if ( get_transient( 'perfectpixel_fatal_error_mailed' ) ) {
		return; // Throttle: one email every 15 minutes.
	}
	set_transient( 'perfectpixel_fatal_error_mailed', 1, 15 * MINUTE_IN_SECONDS );
	$recipient = sanitize_email( '{{fatal_error_recipient}}' );
	$url       = ( is_ssl() ? 'https://' : 'http://' ) . ( $_SERVER['HTTP_HOST'] ?? '' ) . ( $_SERVER['REQUEST_URI'] ?? '' );
	$message   = sprintf(
		"Fatal error στο %s\n\nΜήνυμα: %s\nΑρχείο: %s\nΓραμμή: %s\nΣελίδα: %s\n\nΔείτε WooCommerce → Κατάσταση → Αρχεία καταγραφής (fatal-errors).",
		home_url(),
		$error['message'] ?? '',
		$error['file'] ?? '',
		$error['line'] ?? '',
		esc_url_raw( $url )
	);
	wp_mail( $recipient ? $recipient : get_option( 'admin_email' ), '[' . wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) . '] Fatal error', $message );
}
